function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const result: any = {type: 'list_sessions'};

  if ('limit' in message) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'limit must be a non-negative integer'};
    }
    if (message.limit < 1 || message.limit > 200) {
      return {valid: false, error: 'limit must be between 1 and 200'};
    }
    result.limit = message.limit;
  }

  if ('before' in message) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'before must be an object'};
    }
    const before = message.before as Record<string, unknown>;

    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
      return {valid: false, error: 'before.sessionId must be 1-128 chars'};
    }

    if (typeof before.updatedAt === 'string') {
      const date = Date.parse(before.updatedAt);
      if (Number.isNaN(date)) {
        return {valid: false, error: 'before.updatedAt must be a valid date string or number'};
      }
    } else if (typeof before.updatedAt === 'number') {
      if (!Number.isFinite(before.updatedAt)) {
        return {valid: false, error: 'before.updatedAt must be a valid date string or number'};
      }
    } else {
      return {valid: false, error: 'before.updatedAt must be a valid date string or number'};
    }

    result.before = {
      sessionId: before.sessionId,
      updatedAt: before.updatedAt
    };
  }

  return {
    valid: true,
    data: result
  };
}

